  damage(p,n){if(!p?.alive)return{dead:true,transform:false};if(p.possession){const hostName=defOf(p).name;this.breakPossession(p);return{dead:false,transform:false,possessionBroken:true,hostName};}let pending=Math.max(0,Number(n)||0);for(const e of p.effects||[]){if(!pending)break;const temp=Math.max(0,Number(e.tempLife)||0);if(!temp)continue;const used=Math.min(temp,pending);e.tempLife=temp-used;pending-=used;}p.hp-=n;if(p.name==='Golem'&&!p.form&&p.hp>0){p.form='lava';p.hp=1+(p.bonusV||0);return{dead:false,transform:true};}if(p.hp<=0){const zombieWasFirst=(p.identity||p.name)==='Zumbi'&&p.original&&!p.zombieRevived;this.kill(p);return{dead:!zombieWasFirst&&!p.alive,transform:false,zombieDown:zombieWasFirst};}return{dead:false,transform:false};}
