  tickPieceEffects(p,tick){if(!p?.alive||!p.effects?.length)return;const keep=[];for(const e0 of p.effects){const e={...e0};if((e.tick||'round')===tick&&Number.isFinite(Number(e.remaining)))e.remaining=Number(e.remaining)-1;if(Number(e.remaining)>0||e.tick==='bardTurn'){keep.push(e);continue;}this.addHistory(p.owner,`⏳ ${e.name||'Efeito'} terminou em ${defOf(p).name}.`);if(e.onExpire==='despawn'){this.clearShieldLinks(p);p.alive=false;}}p.effects=keep;const max=defOf(p).v;if(p.hp>max)p.hp=max;}
  finishActivation(side){const hadActivation=!!this.s.activation[side],p=this.active(side);if(hadActivation)this.s.roundActivations[side]=(this.s.roundActivations?.[side]||0)+1;if(p?.alive){if(p.name==='Arqueiro'||p.identity==='Arqueiro'){p.sureShotActive=false;if((p.sureShotCooldown||0)>0)p.sureShotCooldown--;}if((p.ninjaSmokeCooldown||0)>0)p.ninjaSmokeCooldown--;if((p.ninjaSmokeRemaining||0)>0&&p.ninjaSmokeCooldown<2)p.ninjaSmokeRemaining--;p.activated=true;const mate=this.shareTurnMate(p);if(mate?.alive)mate.activated=true;this.tickPieceEffects(p,'turn');if((p.identity||p.name)==='Bardo'||this.pieces(p.owner).some(q=>(q.effects||[]).some(e=>e.sourceBardId===p.id)))this.expireBardAfterTurn(p);else p.turnsTaken=(p.turnsTaken||0)+1;if(p.paranoia?.revealed){p.paranoia.remaining--;if(p.paranoia.remaining<=0){p.paranoia=null;this.addIntel(side,'🧠 O efeito de Paranoia terminou.');}}if((p.identity||p.name)==='Zumbi'&&p.zombieTurnsLeft>0){p.zombieTurnsLeft--;if(p.zombieTurnsLeft<=0){this.addHistory(side,'🧟 Os 3 turnos do Zumbi terminaram; ele caiu definitivamente.');this.kill(p,true);}}}this.s.activation[side]=null;this.s.impact[side]=[];if(this.s.combatHold?.[side])this.s.combatHold[side]=false;else if(this.s.combatMarks)this.s.combatMarks[side]=[];this.updateEliminations();if(this.checkEnd())return this.ok('Partida encerrada.',{gameOver:true});this.advance(side);return this.ok('Turno encerrado.',{turn:this.s.turn});}
  updateEliminations(){for(const side of TRI_SIDES){if(this.s.eliminated[side]||this.originalDeaths(side)<3)continue;const siegeBefore=this.siegeActive();this.s.eliminated[side]=true;for(const p of this.pieces(side))if(p.alive){if(p.summonType==='livingBranch'){const c=p.coord;this.s.trees=this.s.trees.filter(t=>t.coord!==c);this.s.trees.push({coord:c,state:'live'});}this.clearShieldLinks(p);p.alive=false;}this.s.mirrors=this.s.mirrors.filter(m=>m.owner!==side);this.s.traps[side]=[];for(const b of this.s.bases)if(b.owner===side)b.disabled=true;for(const x of TRI_SIDES)this.addHistory(x,`☠️ Jogador ${side} foi eliminado da Arena após 3 perdas originais.`);if(!siegeBefore&&this.siegeActive()){const msg='👁️ Cerco Final: não restam Postos ativos sem sabotagem. O contorno externo da Arena agora revela permanentemente qualquer unidade para todos.';for(const x of TRI_SIDES)this.addHistory(x,msg);}}}
