    const opts=this.legalAbilityCells(p).filter(c=>!bases.has(c)&&!solid.has(c));
    return this.pick(opts,c=>this.scoreCell(c)*24+this.hotAround(c)*3+(TRI_MAP.central.includes(c)?3:0)-(own.some(t=>t.coord===c)?18:0));
